-- Standalone process notes and reusable typed templates; no financial posting side effects.
CREATE TABLE app.period_review_templates(workspace_id uuid NOT NULL REFERENCES app.workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),actor_id text NOT NULL DEFAULT app.current_actor_id(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE app.period_review_template_versions(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),template_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object' AND octet_length(definition::text)<=131072 AND definition ?& ARRAY['name','instructions','status','fields'] AND jsonb_typeof(definition->'fields')='array' AND definition->>'status' IN('active','archived')),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),actor_id text NOT NULL DEFAULT app.current_actor_id(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,template_id,version),FOREIGN KEY(workspace_id,template_id) REFERENCES app.period_review_templates(workspace_id,id));
CREATE TABLE app.period_review_entries(workspace_id uuid NOT NULL REFERENCES app.workspaces(id),id uuid NOT NULL DEFAULT gen_random_uuid(),actor_id text NOT NULL DEFAULT app.current_actor_id(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE app.period_review_versions(workspace_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),entry_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),template_version_id uuid,definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object' AND octet_length(definition::text)<=131072 AND definition ?& ARRAY['title','from','to','timezone','status','kind','notes','tradeIds','strategyVersionIds'] AND definition->>'status' IN('draft','final') AND definition->>'kind' IN('daily','session-preparation','session-review','weekly','monthly','custom')),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),actor_id text NOT NULL DEFAULT app.current_actor_id(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,entry_id,version),FOREIGN KEY(workspace_id,entry_id) REFERENCES app.period_review_entries(workspace_id,id),FOREIGN KEY(workspace_id,template_version_id) REFERENCES app.period_review_template_versions(workspace_id,id));
CREATE TABLE app.period_review_commands(workspace_id uuid NOT NULL REFERENCES app.workspaces(id),id uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash~'^[a-f0-9]{64}$'),result jsonb NOT NULL CHECK(octet_length(result::text)<=262144),actor_id text NOT NULL DEFAULT app.current_actor_id(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE app.period_review_trades(workspace_id uuid NOT NULL,review_version_id uuid NOT NULL,trade_id uuid NOT NULL,actor_id text NOT NULL DEFAULT app.current_actor_id(),PRIMARY KEY(workspace_id,review_version_id,trade_id),FOREIGN KEY(workspace_id,review_version_id) REFERENCES app.period_review_versions(workspace_id,id),FOREIGN KEY(workspace_id,trade_id) REFERENCES app.trades(workspace_id,id));
CREATE TABLE app.period_review_strategies(workspace_id uuid NOT NULL,review_version_id uuid NOT NULL,strategy_version_id uuid NOT NULL,actor_id text NOT NULL DEFAULT app.current_actor_id(),PRIMARY KEY(workspace_id,review_version_id,strategy_version_id),FOREIGN KEY(workspace_id,review_version_id) REFERENCES app.period_review_versions(workspace_id,id),FOREIGN KEY(workspace_id,strategy_version_id) REFERENCES app.strategy_versions(workspace_id,id));
--> statement-breakpoint
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['period_review_templates','period_review_template_versions','period_review_entries','period_review_versions','period_review_commands','period_review_trades','period_review_strategies'] LOOP
  EXECUTE format('ALTER TABLE app.%I OWNER TO journal_migrator',t);
  EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY %I ON app.%I FOR SELECT TO journal_app USING(workspace_id=app.current_workspace_id() AND app.actor_role(workspace_id) IS NOT NULL)',t||'_read',t);
  EXECUTE format('CREATE POLICY %I ON app.%I FOR INSERT TO journal_app WITH CHECK(workspace_id=app.current_workspace_id() AND actor_id=app.current_actor_id() AND app.actor_role(workspace_id) IN (''owner'',''editor''))',t||'_insert',t);
  EXECUTE format('REVOKE ALL ON app.%I FROM PUBLIC',t);
  EXECUTE format('GRANT SELECT,INSERT ON app.%I TO journal_app',t);
  EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON app.%I FOR EACH ROW EXECUTE FUNCTION app.reject_accounting_history_mutation()',t||'_immutable',t);
 END LOOP;
END $$;
--> statement-breakpoint
-- Extend the reviewed portable allowlist without broadening it to arbitrary tables.
CREATE OR REPLACE FUNCTION app.portable_workspace_tables() RETURNS TABLE(name text)
LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT item FROM unnest(ARRAY[
 'audit_events','financial_state','currencies','currency_convention_versions','brokers','accounts','account_settings_versions','cash_buckets','instruments','instrument_versions','trades','trade_legs','orders','order_legs','order_revisions','financial_commands','executions','opening_lots','fees','cash_movements','fx_conversions','ledger_events','postings','holding_books','positions','lots','lot_matches','allocation_sets','allocation_items','cost_attribution_sets','cost_allocations','execution_supersessions','fx_observations','price_observations','outbox_events','holding_transfers','inventory_events','trade_closures','account_valuation_observations','strategies','strategy_attachments','strategy_commands','strategy_version_attachments','strategy_versions','trade_strategy_links','journal_commands','journal_entries','journal_plan_attachments','journal_plan_commitments','journal_plan_versions','journal_revision_attachments','journal_revisions','journal_risk_additions','account_cash_events','cash_transfer_receipts','cash_transfers','portfolio_version_accounts','portfolio_versions','portfolios','import_template_versions','import_batches','import_rows','import_operations','import_sources','import_source_history','portable_restore_history','source_statements','statement_reconciliations','risk_policies','risk_policy_versions','risk_commands','risk_assessments','risk_assessment_policies',
 'period_review_templates','period_review_template_versions','period_review_entries','period_review_versions','period_review_commands','period_review_trades','period_review_strategies'
 ]::text[]) item WHERE to_regclass(format('app.%I',item)) IS NOT NULL ORDER BY item
$$;
ALTER FUNCTION app.portable_workspace_tables() OWNER TO journal_migrator;
REVOKE ALL ON FUNCTION app.portable_workspace_tables() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.portable_workspace_tables() TO journal_app;
UPDATE app.schema_metadata SET version=13 WHERE singleton=true;
